stageCss:
#stage .t-scene{ position:relative; width:100%; height:100%; }#stage .t-links{ position:absolute; inset:0; width:100%; height:100%; overflow:visible; }#stage .t-link{
  fill:none; stroke:var(--border); stroke-width:3; stroke-linecap:round;
  opacity:0; transition:opacity .32s ease, stroke .28s ease;
}#stage .t-link.on{ opacity:1; stroke-dasharray:6 12; animation:t-drift 2.6s linear infinite; }#stage .t-link.live{ stroke:var(--accent-1); stroke-dasharray:10 14; animation:t-dash 1s linear infinite; }@keyframes t-dash{ to{ stroke-dashoffset:-48; } }@keyframes t-drift{ to{ stroke-dashoffset:-36; } }#stage .t-node{ position:absolute; height:118px; opacity:0; transform:translateY(20px); transition:all .34s cubic-bezier(.22,1,.36,1); }#stage .t-node.show{ opacity:1; transform:none; }#stage #t-tv{ top:0; left:246px; width:500px; }#stage #t-control{ top:250px; left:0; width:452px; }#stage #t-oca{ top:250px; left:540px; width:452px; }#stage .t-node-title{ color:#fff; font-size:31px; font-weight:800; letter-spacing:-.4px; }#stage .t-node-sub{ color:var(--text-dim); font-family:var(--font-mono); font-size:20px; margin-top:5px; }#stage .t-panelbox{ position:absolute; top:432px; left:0; width:992px; height:372px; }#stage .t-panel{
  position:absolute; inset:0; padding:32px 36px;
  opacity:0; transform:scale(.97); pointer-events:none;
  transition:opacity .3s ease, transform .3s cubic-bezier(.22,1,.36,1);
}#stage .t-panel.on{ opacity:1; transform:none; }#stage .t-hook-line{ color:#fff; font-size:66px; font-weight:900; line-height:1.18; letter-spacing:-2px; }#stage .t-strike{ color:var(--danger); text-decoration:line-through; text-decoration-thickness:5px; }#stage .t-hook-note{ color:var(--text-dim); font-size:26px; font-weight:500; margin-top:26px; line-height:1.4; }#stage .t-code{ font-family:var(--font-mono); font-size:24px; line-height:1.62; margin-top:16px; color:var(--code-plain); }#stage .t-code .t-k{ color:var(--accent-1); font-weight:700; }#stage .t-code .t-ok{ color:var(--success); font-weight:700; }#stage .t-res{ color:var(--text-dim); opacity:0; transition:opacity .2s ease; }#stage .t-res.on{ opacity:1; }#stage .t-ind{ padding-left:34px; color:var(--accent-cyan); }#stage .t-fill-row{ display:flex; align-items:center; gap:22px; margin-top:22px; }#stage .t-fill-when{ color:var(--accent-1); font-family:var(--font-mono); font-size:26px; font-weight:700; white-space:nowrap; }#stage .t-fill-bar{ flex:1; height:26px; border-radius:13px; background:var(--border); overflow:hidden; }#stage .t-fill-bar span{
  display:block; width:0%; height:100%; border-radius:13px;
  background:linear-gradient(90deg, var(--accent-2), var(--accent-cyan));
  transition:width 1.25s cubic-bezier(.4,0,.2,1);
}#stage .t-fill-note{ color:var(--text-dim); font-size:25px; line-height:1.45; margin-top:26px; }#stage .t-ladder{ display:flex; flex-direction:column; gap:12px; margin-top:20px; }#stage .t-rung{
  display:flex; align-items:center; justify-content:space-between;
  padding:14px 22px; border-radius:14px; border:1.5px solid var(--border);
  background:rgba(20,27,43,.6); color:var(--text-dim);
  font-family:var(--font-mono); font-size:24px; font-weight:600;
  transition:all .24s ease;
}#stage .t-rung i{ width:13px; height:13px; border-radius:50%; background:var(--border); display:block; }#stage .t-rung.on{ border-color:var(--accent-1); color:#fff; background:rgba(58,160,255,.12); }#stage .t-rung.on i{ background:var(--accent-cyan); box-shadow:0 0 16px var(--accent-cyan); }#stage .t-metrics{ position:absolute; top:838px; left:0; width:992px; display:flex; gap:20px; }#stage .t-metric{ flex:1; padding:24px 26px; text-align:center; }#stage .t-metric-v{ font-size:56px; font-weight:800; line-height:1; }#stage .t-metric-l{ color:var(--text-dim); font-size:20px; font-weight:600; margin-top:12px; letter-spacing:.4px; }

stages.js:
MSD.cls('#t-tv', 'show', true);
MSD.after(120, function(){ MSD.cls('#t-p-hook', 'on', true); MSD.punch('#t-p-hook'); });
MSD.after(640, function(){ MSD.punch('.t-strike'); MSD.sfx.error(); });

MSD.cls('#t-p-hook', 'on', false);
MSD.cls('#t-tv', 'show', true);
MSD.after(90,  function(){ MSD.cls('#t-control', 'show', true); MSD.punch('#t-control', 1); });
MSD.after(300, function(){ MSD.cls('#t-oca', 'show', true); MSD.punch('#t-oca', 3); });
MSD.after(520, function(){ MSD.cls('#t-link-control, #t-link-oca', 'on', true); MSD.sfx.swipe(); });
MSD.after(780, function(){ MSD.sfx.sparkle(); });

MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.focus('#t-control', '#t-oca');
MSD.cls('#t-control', 'hot', true);
MSD.cls('#t-link-control', 'live', true);
MSD.stream('#t-scene', { count: 5, duration: 600, gap: 480, from: { x: 50, y: 8 }, to: { x: 23, y: 28 } });
MSD.after(420, function(){ MSD.cls('#t-p-manifest', 'on', true); });

MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.cls('#t-control', 'hot', true);
MSD.focus('#t-control', '#t-oca');
MSD.cls('#t-p-manifest', 'on', true);
MSD.cls('#t-p-manifest', 'msd-scan', true);
MSD.qa('#t-p-manifest .t-res').forEach(function(el, i){
  MSD.after(80 + i * 105, function(){ el.classList.add('on'); MSD.sfx.blip(i); });
});
MSD.after(760, function(){ MSD.cls('#t-p-manifest', 'msd-scan', false); MSD.flash('#t-p-manifest'); MSD.sfx.lock(); });

MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.cls('#t-p-manifest', 'on', false);
MSD.cls('#t-control', 'hot', false);
MSD.cls('#t-link-control', 'live', false);
MSD.focus('#t-oca', '#t-control');
MSD.after(120, function(){ MSD.cls('#t-oca', 'hot', true); MSD.punch('#t-oca', 2); });
MSD.after(300, function(){ MSD.cls('#t-p-fill', 'on', true); });

MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.cls('#t-oca', 'hot', true);
MSD.focus('#t-oca', '#t-control');
MSD.cls('#t-p-fill', 'on', true);
MSD.cls('#t-p-fill', 'msd-scan', true);
MSD.after(140, function(){
  var bar = MSD.q('#t-fill-bar-in');
  if(bar) bar.style.width = '100%';
});
MSD.after(1320, function(){
  MSD.cls('#t-p-fill', 'msd-scan', false);
  MSD.flash('#t-p-fill'); MSD.sfx.lock();
});

MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.cls('#t-p-fill', 'on', false);
MSD.cls('#t-oca', 'hot', true);
MSD.focus('#t-oca', '#t-control');
MSD.cls('#t-link-oca', 'live', true);
MSD.stream('#t-scene', { count: 6, duration: 540, gap: 400, from: { x: 77, y: 28 }, to: { x: 50, y: 8 } });
MSD.after(170, function(){ MSD.cls('#t-p-ladder', 'on', true); });
MSD.qa('#t-ladder .t-rung').forEach(function(el, i){
  MSD.after(300 + i * 125, function(){ el.classList.add('on'); MSD.sfx.blip(i); });
});

MSD.unfocus();
MSD.cls('#t-tv, #t-control, #t-oca', 'show', true);
MSD.cls('#t-link-control, #t-link-oca', 'on', true);
MSD.cls('#t-oca', 'hot', true);
MSD.cls('#t-link-oca', 'live', true);
MSD.cls('#t-p-ladder', 'on', true);
MSD.cls('#t-ladder .t-rung', 'on', true);
MSD.stream('#t-scene', { count: 6, duration: 520, gap: 420, silent: true, from: { x: 77, y: 28 }, to: { x: 50, y: 8 } });
MSD.show('.t-metric', 95, true);
MSD.after(110, function(){ MSD.count('#t-m1', 4, 560); MSD.sfx.blip(1); });
MSD.after(320, function(){ MSD.count('#t-m2', 1, 460); MSD.sfx.blip(3); });
MSD.after(530, function(){ MSD.count('#t-m3', 95, 700, { suffix: '%' }); MSD.sfx.blip(5); });
MSD.after(1150, function(){ MSD.sfx.sparkle(); MSD.flash('.t-metric'); });
